/**
 * Everything the pages read from Sanity, shaped for the components. Queries live in ./queries.ts
 * and are typed by ../../sanity.types.ts (generated by `npm run typegen` in the Studio).
 *
 * Page copy may embed values from the site settings as `{{capacity}}`, `{{dateShort}}`, ... (the
 * list is in `varsOf`); they are replaced here, so pages never see the placeholders.
 */
import type { SanityImageSource } from '@sanity/image-url';
import type { Family } from '../data/site';
import type {
  Cta as RawCta,
  Figure as RawFigure,
  Link as RawLink,
  PageHero as RawPageHero,
  Quote as RawQuote,
  Seo as RawSeo,
  Stat as RawStat,
  HOME_SPONSORS_QUERY_RESULT,
  SESSIONS_QUERY_RESULT,
  SPEAKERS_QUERY_RESULT,
} from '../../sanity.types';
import { sanityClient } from './client';
import { urlFor } from './image';
import {
  ABOUT_PAGE_QUERY,
  AGENDA_PAGE_QUERY,
  FAQ_PAGE_QUERY,
  FAQ_QUERY,
  HOME_PAGE_QUERY,
  HOME_SPONSORS_QUERY,
  ORGANIZERS_PAGE_QUERY,
  ORGANIZERS_QUERY,
  SESSIONS_QUERY,
  SITE_SETTINGS_QUERY,
  SPEAKERS_PAGE_QUERY,
  SPEAKERS_QUERY,
  SPONSOR_TIERS_QUERY,
  SPONSORS_PAGE_QUERY,
  TRACKS_QUERY,
} from './queries';

const TBC = 'Speaker por confirmar';

/** "María José Vera" → "MV". Fallback when a person has no explicit initials. */
function initialsOf(name: string): string {
  const words = name.trim().split(/\s+/);
  const picked = words.length > 1 ? [words[0], words[words.length - 1]] : words;
  return picked
    .map((w) => w?.charAt(0) ?? '')
    .join('')
    .toUpperCase();
}

/* Placeholders --------------------------------------------------------------------------------- */

type Vars = Record<string, string | number>;

const PLACEHOLDER = /\{\{\s*(\w+)\s*\}\}/g;

function fill(text: string, vars: Vars): string {
  return text.replace(PLACEHOLDER, (match, key: string) =>
    key in vars ? String(vars[key]) : match,
  );
}

/** Replaces the placeholders in every string of a fetched document, however deep. */
function fillDeep<T>(value: T, vars: Vars): T {
  if (typeof value === 'string') return fill(value, vars) as T;
  if (Array.isArray(value)) return value.map((item) => fillDeep(item, vars)) as T;
  if (value && typeof value === 'object') {
    return Object.fromEntries(
      Object.entries(value).map(([key, item]) => [key, fillDeep(item, vars)]),
    ) as T;
  }
  return value;
}

/* Shared shapes -------------------------------------------------------------------------------- */

export interface Link {
  label: string;
  href: string;
}

/** The register block that closes every page. */
export interface Cta {
  eyebrow: string;
  title: string;
  lead: string;
  primary: Link;
  secondary: Link;
}

export interface Seo {
  /** Page name, shown before " · DevFest Guayaquil 2026". */
  title: string;
  description: string;
}

export interface PageHero {
  eyebrow: string;
  title: string;
  lead: string;
  /** Glyph file names under /assets/glyphs, decoration only. */
  glyphs: string[];
}

export interface Stat {
  value: string;
  suffix?: string;
  label: string;
  /** Set when `value` is a whole number, for the count-up animation (`data-count`). */
  count?: number;
}

export interface Figure {
  src: string;
  alt: string;
  /** Chip in the corner of the photo. */
  tag?: string;
}

export interface Quote {
  /** Bold opening word(s). */
  highlight?: string;
  text: string;
  attribution?: string;
}

const toLink = (l: RawLink): Link => ({ label: l.label, href: l.href });

const toSeo = (s: RawSeo): Seo => ({ title: s.title, description: s.description });

const toPageHero = (h: RawPageHero): PageHero => ({
  eyebrow: h.eyebrow,
  title: h.title,
  lead: h.lead,
  glyphs: h.glyphs ?? [],
});

function toStat(s: RawStat): Stat {
  const value = s.value.trim();
  return {
    value,
    suffix: s.suffix ?? undefined,
    label: s.label,
    count: /^\d+$/.test(value) ? Number(value) : undefined,
  };
}

const toQuote = (q: RawQuote): Quote => ({
  highlight: q.highlight ?? undefined,
  text: q.text,
  attribution: q.attribution ?? undefined,
});

/** Square crop (the notch media is 1:1), honouring the hotspot set in the Studio. */
function toFigure(f: RawFigure): Figure | undefined {
  if (!f.image?.asset) return undefined;
  return {
    // The generated image type is structurally a SanityImageSource; the cast only bridges names.
    src: urlFor(f.image as SanityImageSource)
      .width(1000)
      .height(1000)
      .fit('crop')
      .auto('format')
      .url(),
    alt: f.image.alt ?? '',
    tag: f.tag ?? undefined,
  };
}

/* Site settings ------------------------------------------------------------------------------ */

export interface FooterColumn {
  heading: string;
  links: Link[];
}

export interface SiteSettings {
  name: string;
  year: number;
  /** "DevFest Guayaquil 2026", used in page titles. */
  title: string;
  /** ISO date, e.g. 2026-12-05 */
  date: string;
  /** "5 de diciembre, 2026" */
  dateShort: string;
  /** "5 de diciembre de 2026" */
  dateLong: string;
  venue: string;
  capacity: number;
  /** Registration form, or '#' while it does not exist yet. */
  registerHref: string;
  email: string;
  sponsorsEmail: string;
  communityUrl: string;
  /** communityUrl without protocol, e.g. gdg.community.dev/guayaquil */
  communityLabel: string;
  handle: string;
  /** Social profile, or '#' when not set. */
  socialHref: string;
  /** Header menu, in order. */
  navigation: Link[];
  /** Default register block; a page can override parts of it. */
  registerCta: Cta;
  footer: {
    columns: FooterColumn[];
    /** Heading of the column built from the community, social and email links. */
    followHeading: string;
    tagline: string;
  };
}

function formatEventDate(iso: string) {
  const date = new Date(`${iso}T12:00:00Z`);
  const part = (options: Intl.DateTimeFormatOptions) =>
    new Intl.DateTimeFormat('es-EC', { timeZone: 'UTC', ...options }).format(date);
  const day = part({ day: 'numeric' });
  const month = part({ month: 'long' });
  const year = part({ year: 'numeric' });
  return { short: `${day} de ${month}, ${year}`, long: `${day} de ${month} de ${year}` };
}

type SiteVarsSource = Pick<
  SiteSettings,
  | 'name'
  | 'year'
  | 'title'
  | 'dateShort'
  | 'dateLong'
  | 'venue'
  | 'capacity'
  | 'email'
  | 'sponsorsEmail'
  | 'handle'
>;

/** The values `{{...}}` placeholders in page copy resolve to. */
const varsOf = (s: SiteVarsSource): Vars => ({
  name: s.name,
  year: s.year,
  title: s.title,
  dateShort: s.dateShort,
  dateLong: s.dateLong,
  venue: s.venue,
  capacity: s.capacity,
  email: s.email,
  sponsorsEmail: s.sponsorsEmail,
  handle: s.handle,
});

async function loadSiteSettings(): Promise<SiteSettings> {
  const s = await sanityClient.fetch(SITE_SETTINGS_QUERY);
  if (!s) {
    throw new Error(
      'No existe el documento "siteSettings" en Sanity. Ejecuta `npm run seed` en studio-gdg-gye-devfest o créalo desde el Studio.',
    );
  }
  if (!s.navigation || !s.registerCta || !s.footer) {
    throw new Error(
      'La configuración del sitio no tiene menú, bloque de registro o pie de página. Ejecuta `npm run seed:pages` en studio-gdg-gye-devfest o complétala desde el Studio.',
    );
  }
  const { short, long } = formatEventDate(s.date);
  const registerHref = s.registerUrl ?? '#';
  const base = {
    name: s.name,
    year: s.year,
    title: `${s.name} ${s.year}`,
    date: s.date,
    dateShort: short,
    dateLong: long,
    venue: s.venue,
    capacity: s.capacity,
    registerHref,
    email: s.email,
    sponsorsEmail: s.sponsorsEmail,
    communityUrl: s.communityUrl,
    communityLabel: s.communityUrl.replace(/^https?:\/\//, '').replace(/\/$/, ''),
    handle: s.handle,
    socialHref: s.socialUrl ?? '#',
  };
  const chrome = fillDeep(
    { navigation: s.navigation, registerCta: s.registerCta, footer: s.footer },
    varsOf(base),
  );
  return {
    ...base,
    navigation: chrome.navigation.map(toLink),
    registerCta: {
      eyebrow: chrome.registerCta.eyebrow,
      title: chrome.registerCta.title,
      lead: chrome.registerCta.lead,
      primary: { label: chrome.registerCta.primaryLabel, href: registerHref },
      secondary: toLink(chrome.registerCta.secondary),
    },
    footer: {
      columns: chrome.footer.columns.map((c) => ({
        heading: c.heading,
        links: c.links.map(toLink),
      })),
      followHeading: chrome.footer.followHeading,
      tagline: chrome.footer.tagline,
    },
  };
}

let settingsPromise: Promise<SiteSettings> | undefined;

/** Fetched once per build. In dev every request re-fetches so Studio edits show up on reload. */
export function getSiteSettings(): Promise<SiteSettings> {
  if (import.meta.env.DEV || !settingsPromise) settingsPromise = loadSiteSettings();
  return settingsPromise;
}

/* Pages -------------------------------------------------------------------------------------- */

interface PageBase {
  seo: Seo;
  family: Family;
  /** Register block, with the page's overrides applied on top of the site default. */
  cta: Cta;
}

interface RawPageBase {
  seo: RawSeo;
  family: Family;
  cta: RawCta | null;
}

/** Fetches a page singleton, fails loudly when it is missing, and fills in the placeholders. */
async function loadPage<T extends RawPageBase>(
  id: string,
  fetchPage: () => Promise<T | null>,
): Promise<{ page: T; settings: SiteSettings }> {
  const [settings, raw] = await Promise.all([getSiteSettings(), fetchPage()]);
  if (!raw) {
    throw new Error(
      `No existe el documento "${id}" en Sanity. Ejecuta \`npm run seed:pages\` en studio-gdg-gye-devfest o créalo desde el Studio.`,
    );
  }
  return { page: fillDeep(raw, varsOf(settings)), settings };
}

function pageBase(p: RawPageBase, settings: SiteSettings): PageBase {
  const d = settings.registerCta;
  const o = p.cta;
  return {
    seo: toSeo(p.seo),
    family: p.family,
    cta: {
      eyebrow: o?.eyebrow ?? d.eyebrow,
      title: o?.title ?? d.title,
      lead: o?.lead ?? d.lead,
      primary: o?.primary ? toLink(o.primary) : d.primary,
      secondary: o?.secondary ? toLink(o.secondary) : d.secondary,
    },
  };
}

export interface HomePage extends PageBase {
  hero: {
    /** The first chip is tinted. */
    chips: string[];
    title: string;
    lead: string;
    primary: Link;
    secondary: Link;
    figure?: Figure;
    glyphs: string[];
  };
  stats: Stat[];
  speakers: { eyebrow: string; title: string; lead: string; featured: SpeakerCard[]; link: Link };
  tracks: { eyebrow: string; title: string; linkLabel: string };
  quote: Quote;
  sponsors: { eyebrow: string; title: string; link: Link };
}

export async function getHomePage(): Promise<HomePage> {
  const { page: p, settings } = await loadPage('homePage', () =>
    sanityClient.fetch(HOME_PAGE_QUERY),
  );
  return {
    ...pageBase(p, settings),
    hero: {
      chips: p.hero.chips ?? [],
      title: p.hero.title,
      lead: p.hero.lead,
      primary: toLink(p.hero.primary),
      secondary: toLink(p.hero.secondary),
      figure: toFigure(p.hero.figure),
      glyphs: p.hero.glyphs ?? [],
    },
    stats: p.stats.map(toStat),
    speakers: {
      eyebrow: p.speakers.eyebrow,
      title: p.speakers.title,
      lead: p.speakers.lead,
      featured: (p.speakers.featured ?? []).map(toSpeakerCard),
      link: toLink(p.speakers.link),
    },
    tracks: {
      eyebrow: p.tracks.eyebrow,
      title: p.tracks.title,
      linkLabel: p.tracks.linkLabel,
    },
    quote: toQuote(p.quote),
    sponsors: {
      eyebrow: p.sponsors.eyebrow,
      title: p.sponsors.title,
      link: toLink(p.sponsors.link),
    },
  };
}

