/* Tracks ------------------------------------------------------------------------------------- */

export interface TrackCard {
  /** URL-safe id, used for the agenda tab and panel ids. */
  slug: string;
  name: string;
  family: Family;
  room: string;
  /** File name under /assets/glyphs, decoration only. */
  glyph: string;
  blurb: string;
}

export async function getTracks(): Promise<TrackCard[]> {
  const tracks = await sanityClient.fetch(TRACKS_QUERY);
  return tracks.map((t) => ({
    slug: t.slug ?? t._id,
    name: t.name,
    family: t.family,
    room: t.room,
    glyph: t.glyph,
    blurb: t.blurb,
  }));
}

/* Speakers ----------------------------------------------------------------------------------- */

export interface SpeakerCard {
  id: string;
  name: string;
  role: string;
  initials: string;
  family: Family;
  /** Track name, shown as the card chip. */
  track: string;
  /** Title of the speaker's session, once it is on the agenda. */
  talk?: string;
}

type RawSpeaker = SPEAKERS_QUERY_RESULT[number];

function toSpeakerCard(s: RawSpeaker): SpeakerCard {
  return {
    id: s._id,
    name: s.name,
    role: s.role,
    initials: s.initials ?? initialsOf(s.name),
    family: s.family,
    track: s.track.name,
    talk: s.talk ?? undefined,
  };
}

export async function getSpeakers(): Promise<SpeakerCard[]> {
  const speakers = await sanityClient.fetch(SPEAKERS_QUERY);
  return speakers.map(toSpeakerCard);
}

/* Agenda ------------------------------------------------------------------------------------- */

export interface Chip {
  label: string;
  /** chip modifier class (BEM), e.g. 'chip--tint' */
  cls?: string;
}

export interface Session {
  time: string;
  title: string;
  who?: string;
  chips?: Chip[];
  isBreak?: boolean;
}

export interface TrackSchedule {
  track: TrackCard;
  sessions: Session[];
}

type RawSession = SESSIONS_QUERY_RESULT[number];

function toSessionRow(s: RawSession): Session {
  const time = `${s.startTime} – ${s.endTime}`;
  const room = s.room ?? s.track?.room;
  // Plenary rows without a speaker line: breaks and the closing panel.
  if (s.kind === 'break' || s.kind === 'panel') {
    return { time, title: room ? `${s.title} · ${room}` : s.title, isBreak: true };
  }
  const chips: Chip[] = [];
  if (s.kind === 'keynote') chips.push({ label: 'Keynote', cls: 'chip--tint' });
  else if (s.track) chips.push({ label: s.track.name, cls: `chip--${s.track.family}` });
  if (room) chips.push({ label: room });
  return {
    time,
    title: s.title,
    who: s.speaker ? `${s.speaker.name} / ${s.speaker.role}` : TBC,
    chips,
  };
}

/** One tab per track: its own sessions plus the plenary ones (keynote, panel, breaks), by time. */
export async function getSchedule(): Promise<TrackSchedule[]> {
  const [tracks, sessions] = await Promise.all([getTracks(), sanityClient.fetch(SESSIONS_QUERY)]);
  return tracks.map((track) => ({
    track,
    sessions: sessions.filter((s) => !s.track || s.track.slug === track.slug).map(toSessionRow),
  }));
}

