/* Sponsors ----------------------------------------------------------------------------------- */

export interface SponsorTile {
  id: string;
  name: string;
  /** Sponsor site, or '#' when not set. */
  href: string;
  /** Present once a logo has been uploaded; the tile shows the name until then. */
  logo?: { src: string; alt: string };
}

export interface SponsorTierSection {
  id: string;
  name: string;
  kind: 'paid' | 'community';
  headline: string;
  description?: string;
  perks: string[];
  family: Family;
  sponsors: SponsorTile[];
}

type RawSponsor = HOME_SPONSORS_QUERY_RESULT[number];

function toSponsorTile(s: RawSponsor): SponsorTile {
  return {
    id: s._id,
    name: s.name,
    href: s.url ?? '#',
    logo: s.logo?.asset
      ? {
          // The generated image type is structurally a SanityImageSource; the cast only bridges names.
          src: urlFor(s.logo as SanityImageSource)
            .width(480)
            .height(240)
            .fit('max')
            .auto('format')
            .url(),
          alt: s.logo.alt ?? s.name,
        }
      : undefined,
  };
}

export async function getSponsorTiers(): Promise<SponsorTierSection[]> {
  const tiers = await sanityClient.fetch(SPONSOR_TIERS_QUERY);
  return tiers.map((t) => ({
    id: t._id,
    name: t.name,
    kind: t.kind,
    headline: t.headline,
    description: t.description ?? undefined,
    perks: t.perks ?? [],
    family: t.family,
    sponsors: t.sponsors.map(toSponsorTile),
  }));
}

/** Teaser tiles on the home page. */
export async function getHomeSponsors(): Promise<SponsorTile[]> {
  const sponsors = await sanityClient.fetch(HOME_SPONSORS_QUERY);
  return sponsors.map(toSponsorTile);
}

